public async Task<Product> GetProductAsync(string id)
{
    // Try cache first
    var cached = await _cache.StringGetAsync(id);
    if (cached.HasValue)
        return JsonSerializer.Deserialize<Product>(cached!);

    // Cache miss - fetch from DB
    var product = await _db.Products.FindAsync(id);
    if (product == null) return null;

    // Cache for 5 minutes
    await _cache.StringSetAsync(id, JsonSerializer.Serialize(product), TimeSpan.FromMinutes(5));
    return product;
}

public async Task UpdateProductAsync(Product product)
{
    await _db.Products.UpdateAsync(product);
    // Invalidate cache
    await _cache.KeyDeleteAsync(product.Id);
}
